void Compute(OpKernelContext* context) override {
  const Tensor& input = context->input(0);
  const TensorShape& input_shape = input.shape();
  const int32 input_dims = input_shape.dims();

  const Tensor& segment_id = context->input(1);
  const TensorShape& segment_id_shape = segment_id.shape();
  const int32 segment_dims = segment_id_shape.dims();

  const Tensor& num_segments_tensor = context->input(2);
  auto num_segments = num_segments_tensor.scalar<NUM_SEGMENTS_TYPE>()();

  OP_REQUIRES(context, segment_dims != 0,
              errors::InvalidArgument("Segment_id cannot have rank 0"));

  OP_REQUIRES(
      context, segment_dims <= input_dims,
      errors::OutOfRange("Invalid segment_id rank ", segment_dims,
                         " for input with ", input_dims, " dimension(s)"));
  for (auto i = 0; i < segment_dims; i++) {
    OP_REQUIRES(
        context, segment_id_shape.dim_size(i) == input_shape.dim_size(i),
        errors::InvalidArgument(
            "Segment dimension is ", segment_id_shape.dim_size(i),
            " while input dimension is ", input_dims, " in rank ", i));
  }

  // Making output tensor.
  Tensor* output_tensor = nullptr;
  TensorShape output_shape =
      GetOutputShape(input_shape, segment_id_shape, num_segments);
  OP_REQUIRES_OK(context, context->allocate_output("output", output_shape,
                                                   &output_tensor));

  // Preparating flat tensors.
  auto output_flat = output_tensor->flat<tstring>();
  auto flat_segment_id = segment_id.flat<INDICES_TYPE>();
  auto flat_input = input.flat<tstring>();

  for (int i = 0; i < flat_segment_id.size(); i++) {
    OP_REQUIRES(
        context,
        ((flat_segment_id(i) < num_segments) && (flat_segment_id(i) >= 0)),
        errors::InvalidArgument(
            "segment_ids are not allowed to exceed num_segments or"
            " to have negative values."));
  }

  int64 big_stride;
  int64 small_stride;
  std::tie(big_stride, small_stride) =
      GetStrides<INDICES_TYPE>(input_shape, segment_id_shape);
  auto relative_offset_set =
      GetFlattenedRelativeOffsets<INDICES_TYPE>(small_stride, big_stride);
  for (auto start_offset = 0; start_offset < big_stride; start_offset++) {
    for (auto i = 0; i < relative_offset_set.size(); i++) {
      auto output_index = start_offset + flat_segment_id(i) * big_stride;
      auto offset = start_offset + relative_offset_set[i];
      if (output_flat(output_index).length() != 0)
        output_flat(output_index).append(separator_.c_str());
      output_flat(output_index).append(flat_input(offset));
    }
  }
}

vidtv_s302m_compute_sample_count_from_video(struct vidtv_encoder *e)
{
	struct vidtv_access_unit *sync_au = e->sync->access_units;
	struct vidtv_access_unit *au = e->access_units;
	u32 sample_duration_usecs;
	u32 vau_duration_usecs;
	u32 s;

	vau_duration_usecs    = USEC_PER_SEC / e->sync->sampling_rate_hz;
	sample_duration_usecs = USEC_PER_SEC / e->sampling_rate_hz;

	while (au && sync_au) {
		s = DIV_ROUND_UP(vau_duration_usecs, sample_duration_usecs);
		au->num_samples = s;
		au = au->next;
		sync_au = sync_au->next;
	}
}

static void nfc_generate_mf_ultralight_c(NfcDevice* nfc_device) {
    MfUltralightData* mfu_data = mf_ultralight_alloc();
    nfc_generate_mf_ul_common(mfu_data);

    mfu_data->type = MfUltralightTypeMfulC;
    mfu_data->pages_total = 48; // MF0ICU2: 48 pages, 0x00-0x2F
    mfu_data->pages_read = 48;
    mfu_data->page[2].data[1] = 0x48; // Internal byte (default)

    // AUTH0 (page 0x2A byte 0) = 0x30 protects nothing, so the card reads without authentication; if
    // the user later lowers it, the default 3DES key at pages 0x2C-0x2F (used as-is by the listener
    // via mf_ultralight_3des_get_key) is a known dictionary entry, so it stays unlockable. UL-C has
    // no GetVersion and no originality signature, so version/signature stay zeroed.
    mfu_data->page[0x2A].data[0] = 0x30;
    memcpy(
        &mfu_data->page[0x2C], mf_ultralight_c_default_key, sizeof(mf_ultralight_c_default_key));

    nfc_device_set_data(nfc_device, NfcProtocolMfUltralight, mfu_data);
    mf_ultralight_free(mfu_data);
}

static int prefix_images(waste_ctx *c, const opts *o, char *buf, size_t cap)
{
    size_t k = 0;
    for (int i = 0; i < o->n_image; i++) {
        size_t rows = 0;
        const waste_status st = waste_image_add(c, o->image[i], &rows);
        if (st != WASTE_OK) return fail(o->image[i], st);
        if (!o->quiet)
            fprintf(stderr, "[%s: %zu image tokens]\n", o->image[i], rows);
        const int w = snprintf(buf + k, cap - k, "%s%s%s%s",
                               "<|media_begin|>", "<|media_content|>",
                               "<|media_pad|>", "<|media_end|>");
        if (w < 0 || (size_t)w >= cap - k) {
            fprintf(stderr, "prompt too long\n");
            return 1;
        }
        k += (size_t)w;
    }
    buf[k] = 0;
    return 0;
}

std::string generate_receive_log(const std::string &msg) {
    std::time_t now = std::time(nullptr);
    std::tm *t = std::localtime(&now);
    std::ostringstream timestamp;
    timestamp << std::put_time(t, "%Y-%m-%dT%H:%M:%S");
    std::ostringstream log_entry;
    log_entry << "[" << timestamp.str() << "] Received: " << msg;
    return log_entry.str();
}

