void flb_test_file_rotation_multithreaded(void)
{
    int ret;
    int i;
    char *p = (char *)JSON_SMALL;
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    char logfile[512];
    pthread_t threads[8];
    struct thread_data thread_data[8];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int success = 1;
    int num_threads = 4;
    int events_per_thread = 10;
    FILE *fp;
    char *content;
    size_t content_size;
    int line_count = 0;

    recursive_delete_directory(TEST_LOGPATH);
    TEST_MKDIR(TEST_LOGPATH);
    snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "%s", TEST_LOGPATH,
             "test_multithreaded.log");

    ctx = flb_create();
    TEST_ASSERT(flb_service_set(ctx, "Flush", "0.5", "Grace", "2", "Log_Level",
                                "error", NULL) == 0);

    in_ffd = flb_input(ctx, (char *)"lib", NULL);
    TEST_CHECK(in_ffd >= 0);
    flb_input_set(ctx, in_ffd, "tag", "test", NULL);

    out_ffd = flb_output(ctx, (char *)"file", NULL);
    TEST_CHECK(out_ffd >= 0);
    TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test", "file", logfile,
                               "rotate", "true", "rotate_max_size", "1M",
                               "rotate_max_files", "5", "rotate_gzip", "false",
                               NULL) == 0);

    ret = flb_start(ctx);
    TEST_CHECK(ret == 0);

    for (i = 0; i < num_threads; i++) {
        thread_data[i].ctx = ctx;
        thread_data[i].in_ffd = in_ffd;
        thread_data[i].thread_id = i;
        thread_data[i].events_per_thread = events_per_thread;
        thread_data[i].json_data = p;
        thread_data[i].json_len = strlen(p);
        thread_data[i].success = &success;
        thread_data[i].mutex = &mutex;
    }

    for (i = 0; i < num_threads; i++) {
        ret = pthread_create(&threads[i], NULL, thread_worker, &thread_data[i]);
        TEST_CHECK(ret == 0);
    }

    for (i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    flb_time_msleep(3000);

    ret = wait_for_file_size(logfile, 100 * 1024, TEST_TIMEOUT);
    TEST_CHECK(ret == 0);

    flb_stop(ctx);
    flb_destroy(ctx);

    TEST_CHECK(success == 1);

    fp = fopen(logfile, "r");
    TEST_CHECK(fp != NULL);
    if (fp) {
        char line[4096];
        while (fgets(line, sizeof(line), fp) != NULL) {
            line_count++;
        }
        fclose(fp);
    }

    TEST_CHECK(line_count >= num_threads * events_per_thread);

    content = read_file_content(logfile, &content_size);
    TEST_CHECK(content != NULL);
    if (content) {
        TEST_CHECK(strstr(content, "test") != NULL);
        TEST_CHECK(strstr(content, "1448403340") != NULL);
        int key_count = 0;
        char *pos = content;
        while ((pos = strstr(pos, "key_0")) != NULL) {
            key_count++;
            pos++;
        }
        TEST_CHECK(key_count >= num_threads * events_per_thread);
        flb_free(content);
    }

    pthread_mutex_destroy(&mutex);

    recursive_delete_directory(TEST_LOGPATH);
}

rdpdr_process(STREAM s)
{
	uint32 handle;
 	uint16 vmin;
 	uint16 component;
 	uint16 pakid;

 	logger(Protocol, Debug, "rdpdr_process()");
 	/* hexdump(s->p, s->end - s->p); */

	in_uint16(s, component);
	in_uint16(s, pakid);

	if (component == RDPDR_CTYP_CORE)
	{
		switch (pakid)
		{
			case PAKID_CORE_DEVICE_IOREQUEST:
				rdpdr_process_irp(s);
				break;

			case PAKID_CORE_SERVER_ANNOUNCE:
 				/* DR_CORE_SERVER_ANNOUNCE_REQ */
 				in_uint8s(s, 2);	/* skip versionMajor */
 				in_uint16_le(s, vmin);	/* VersionMinor */
 				in_uint32_le(s, g_client_id);	/* ClientID */

 				/* The RDP client is responsibility to provide a random client id
 				   if server version is < 12 */
 				if (vmin < 0x000c)
					g_client_id = 0x815ed39d;	/* IP address (use 127.0.0.1) 0x815ed39d */
				g_epoch++;

#if WITH_SCARD
				/*
				 * We need to release all SCARD contexts to end all
				 * current transactions and pending calls
				 */
				scard_release_all_contexts();

				/*
				 * According to [MS-RDPEFS] 3.2.5.1.2:
				 *
				 * If this packet appears after a sequence of other packets,
				 * it is a signal that the server has reconnected to a new session
				 * and the whole sequence has been reset. The client MUST treat
				 * this packet as the beginning of a new sequence.
				 * The client MUST also cancel all outstanding requests and release
				 * previous references to all devices.
				 *
				 * If any problem arises in the future, please, pay attention to the
				 * "If this packet appears after a sequence of other packets" part
				 *
				 */

#endif

				rdpdr_send_client_announce_reply();
				rdpdr_send_client_name_request();
				break;

			case PAKID_CORE_CLIENTID_CONFIRM:
				rdpdr_send_client_device_list_announce();
				break;

			case PAKID_CORE_DEVICE_REPLY:
				in_uint32(s, handle);
				logger(Protocol, Debug,
				       "rdpdr_process(), server connected to resource %d", handle);
				break;

			case PAKID_CORE_SERVER_CAPABILITY:
				rdpdr_send_client_capability_response();
				break;

			default:
				logger(Protocol, Debug,
				       "rdpdr_process(), pakid 0x%x of component 0x%x", pakid,
				       component);
				break;

		}
	}
	else if (component == RDPDR_CTYP_PRN)
	{
		if (pakid == PAKID_PRN_CACHE_DATA)
			printercache_process(s);
	}
	else
		logger(Protocol, Warning, "rdpdr_process(), unhandled component 0x%x", component);
}

