mkdir_recurse(char_u *dir, int prot)
{
    char_u	*p;
    char_u	*updir;
    int		r = FAIL;

    // Get end of directory name in "dir".
    // We're done when it's "/" or "c:/".
    p = gettail_sep(dir);
    if (p <= get_past_head(dir))
	return OK;

    // If the directory exists we're done.  Otherwise: create it.
    updir = vim_strnsave(dir, p - dir);
    if (updir == NULL)
	return FAIL;
    if (mch_isdir(updir))
	r = OK;
    else if (mkdir_recurse(updir, prot) == OK)
	r = vim_mkdir_emsg(updir, prot);
    vim_free(updir);
    return r;
}

atic void BuildPopup(AnnotTextPopup* popup, Annotation* annot) {
    int margin = DpiScale(kMargin);
    int width = PopupWidth(popup->win);

    auto* title = NewVirtText({
        .s = PopupTitleTemp(annot),
        .font = GetBoldPlatformFont(popup->font),
        .textColor = PopupText(),
        .ellipsis = true,
    });

    // CRLF is what a win32 edit expects; annotation text uses bare LF
    Str s = Contents(annot);
    s = str::ReplaceTemp(s, StrL("\r\n"), StrL("\n"));
    s = str::ReplaceTemp(s, StrL("\n"), StrL("\r\n"));
    popup->edit->SetText(s);

    int textDx = width - (2 * margin);
    popup->edit->idealDx = textDx;
    auto* slot = new AnnotTextSlot();
    slot->edit = popup->edit;

    // The card grows to the comment instead of showing a fixed number of
    // lines: give the edit its final width so the text wraps the way it will
    // be read, then ask it how many lines that came to.
    Rect canvas = HwndClientRect(popup->win->hwndCanvas);
    int maxTextDy = std::max(canvas.dy * kMaxHeightPercent / 100, DpiScale(80));
    popup->edit->SetBounds(Rect(0, 0, textDx, maxTextDy));
    popup->edit->idealSizeLines = 1;
    int lineDy = popup->edit->GetIdealSize().dy;
    int nLines = (int)SendMessageW(popup->edit->hwnd, EM_GETLINECOUNT, 0, 0);
    int maxLines = lineDy > 0 ? std::max(maxTextDy / lineDy, kMinLines) : kMinLines;
    popup->edit->idealSizeLines = std::max(kMinLines, std::min(nLines, maxLines));
    int textDy = std::min(popup->edit->GetIdealSize().dy, maxTextDy);
    slot->idealSize = {textDx, textDy};

    auto* column = new VBox();
    column->alignMain = MainAxisAlign::MainStart;
    column->alignCross = CrossAxisAlign::Stretch;
    column->gap = DpiScale(kGap);
    column->AddChild(title);
    column->AddChild(slot);

    auto* content = new Padding(column, Insets{margin, margin, margin, margin});
    popup->size = popup->host->SetLayoutSizedToContent(content);
    popup->host->ClipToRoundedRect(kCornerRadius, popup->size);
    popup->annot = annot;
    popup->tab = popup->win->CurrentTab();
    popup->annotBounds = GetRect(annot);
}

char *read_file_from_dir(const char *filename, const char *dir_path) {
    char* empty_result = malloc(1);
    empty_result[0] = '\0';
    char dir_realpath[1024];
    if (realpath(dir_path, dir_realpath) == NULL) {
        return empty_result;
    }
    char file_path[1024];
    snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, filename);
    char file_realpath[1024];
    if (realpath(file_path, file_realpath) == NULL) {
        return empty_result;
    }
    if (strncmp(file_realpath, dir_realpath, strlen(dir_realpath)) != 0) {
        return empty_result;
    }
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        return empty_result;
    }
    char *content = NULL;
    size_t content_size = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        content = realloc(content, content_size + 1);
        content[content_size++] = ch;
    }
    fclose(file);
    content = realloc(content, content_size + 1);
    content[content_size] = '\0';
    free(empty_result);
    return content;
}

TEST(RotatorTest, DumpOpenRoundtrip) {
  const std::string test_dir = "record_rotator_dump_test_dir/";
  zvec::test_util::RemoveTestPath(test_dir);

  const size_t dim = 128;

  // Build and dump original rotator
  std::shared_ptr<Rotator> original;
  ASSERT_EQ(Rotator::create(&original, dim), 0);
  EXPECT_EQ(original->rotator_type(), RotatorType::FhtKac);

  auto storage = IndexFactory::CreateStorage("MMapFileStorage");
  ASSERT_NE(storage, nullptr);
  zvec::ailego::Params stg_params;
  ASSERT_EQ(0, storage->init(stg_params));
  ASSERT_EQ(0, storage->open(test_dir + "rotator.index", true));
  ASSERT_EQ(0, original->dump(storage));

  // Close and reopen storage
  storage.reset();

  auto storage2 = IndexFactory::CreateStorage("MMapFileStorage");
  ASSERT_NE(storage2, nullptr);
  ASSERT_EQ(0, storage2->init(stg_params));
  ASSERT_EQ(0, storage2->open(test_dir + "rotator.index", false));

  // Load rotator from storage
  std::shared_ptr<Rotator> loaded;
  ASSERT_EQ(0, Rotator::open(&loaded, storage2));

  // Verify metadata
  EXPECT_EQ(original->rotator_type(), loaded->rotator_type());
  EXPECT_EQ(original->dimension(), loaded->dimension());
  EXPECT_TRUE(loaded->initialized());

  // Verify rotate output matches
  std::mt19937 gen(42);
  std::uniform_real_distribution<float> dist(-10.0f, 10.0f);
  std::vector<float> vec(dim);
  for (size_t j = 0; j < dim; ++j) vec[j] = dist(gen);

  auto rotated_orig = original->rotate(vec.data());
  auto rotated_loaded = loaded->rotate(vec.data());

  float max_err = 0.0f;
  for (size_t j = 0; j < dim; ++j)
    max_err = std::max(max_err, std::abs(rotated_orig[j] - rotated_loaded[j]));
  std::cout << "DumpOpen roundtrip max error: " << max_err << std::endl;
  EXPECT_EQ(max_err, 0.0f);

  zvec::test_util::RemoveTestPath(test_dir);
}

