mp_err mp_mul(const mp_int *a, const mp_int *b, mp_int *c)
{
   mp_err err;
   int min_len = MP_MIN(a->used, b->used),
       max_len = MP_MAX(a->used, b->used),
       digs = a->used + b->used + 1;
   mp_sign neg = (a->sign == b->sign) ? MP_ZPOS : MP_NEG;

   if (MP_HAS(S_MP_BALANCE_MUL) &&
       /* Check sizes. The smaller one needs to be larger than the Karatsuba cut-off.
        * The bigger one needs to be at least about one MP_KARATSUBA_MUL_CUTOFF bigger
        * to make some sense, but it depends on architecture, OS, position of the
        * stars... so YMMV.
        * Using it to cut the input into slices small enough for fast_s_mp_mul_digs
        * was actually slower on the author's machine, but YMMV.
        */
       (min_len >= MP_KARATSUBA_MUL_CUTOFF) &&
       ((max_len / 2) >= MP_KARATSUBA_MUL_CUTOFF) &&
       /* Not much effect was observed below a ratio of 1:2, but again: YMMV. */
       (max_len >= (2 * min_len))) {
      err = s_mp_balance_mul(a,b,c);
   } else if (MP_HAS(S_MP_TOOM_MUL) &&
              (min_len >= MP_TOOM_MUL_CUTOFF)) {
      err = s_mp_toom_mul(a, b, c);
   } else if (MP_HAS(S_MP_KARATSUBA_MUL) &&
              (min_len >= MP_KARATSUBA_MUL_CUTOFF)) {
      err = s_mp_karatsuba_mul(a, b, c);
   } else if (MP_HAS(S_MP_MUL_DIGS_FAST) &&
              /* can we use the fast multiplier?
               *
               * The fast multiplier can be used if the output will
               * have less than MP_WARRAY digits and the number of
               * digits won't affect carry propagation
               */
              (digs < MP_WARRAY) &&
              (min_len <= MP_MAXFAST)) {
      err = s_mp_mul_digs_fast(a, b, c, digs);
   } else if (MP_HAS(S_MP_MUL_DIGS)) {
      err = s_mp_mul_digs(a, b, c, digs);
   } else {
      err = MP_VAL;
   }
   c->sign = (c->used > 0) ? neg : MP_ZPOS;
   return err;
}

static int test_deny_openat_creat(void)
{
	struct io_uring ring;
	int ret, failed = 0;
	pid_t pid;
	int status;
	char tmpfile[] = "/tmp/cbpf_test_XXXXXX";
	int tmpfd;

	/* Create a temp file path we can use for testing */
	tmpfd = mkstemp(tmpfile);
	if (tmpfd < 0) {
		perror("mkstemp");
		return 1;
	}
	close(tmpfd);
	unlink(tmpfile);

	pid = fork();
	if (pid < 0) {
		perror("fork");
		return 1;
	}

	if (pid == 0) {
		/* Test that O_CREAT works BEFORE installing filter */
		ret = io_uring_queue_init(8, &ring, 0);
		if (ret < 0) {
			fprintf(stderr, "Child: queue_init failed\n");
			exit(1);
		}

		if (test_openat(&ring, tmpfile, O_CREAT | O_RDWR, 0644,
				"O_CREAT should succeed before filter", 1) != 0)
			failed++;

		/* Clean up created file */
		unlink(tmpfile);

		/* Test that regular open (no O_CREAT) works */
		if (test_openat(&ring, "/dev/null", O_RDONLY, 0,
				"regular open should succeed before filter", 1) != 0)
			failed++;

		io_uring_queue_exit(&ring);

		/* Now install the O_CREAT deny filter */
		ret = register_bpf_filter(deny_o_creat_filter,
					  sizeof(deny_o_creat_filter) / sizeof(deny_o_creat_filter[0]),
					  IORING_OP_OPENAT, 0);
		if (ret < 0) {
			fprintf(stderr, "Child: register failed: %s\n",
				strerror(-ret));
			exit(ret == -EINVAL ? 0 : 1);
		}

		/* Create new ring after filter is installed */
		ret = io_uring_queue_init(8, &ring, 0);
		if (ret < 0) {
			fprintf(stderr, "Child: queue_init 2 failed\n");
			exit(1);
		}

		/* Test that O_CREAT is now denied */
		if (test_openat(&ring, tmpfile, O_CREAT | O_RDWR, 0644,
				"O_CREAT should be denied after filter", 0) != 0)
			failed++;

		/* Test that regular open still works */
		if (test_openat(&ring, "/dev/null", O_RDONLY, 0,
				"regular open should still succeed", 1) != 0)
			failed++;

		io_uring_queue_exit(&ring);
		exit(failed);
	}

	waitpid(pid, &status, 0);
	if (WIFEXITED(status))
		return WEXITSTATUS(status);
	return 1;
}

int waste_model_state_load(waste_model *m, const char *path, int *pos)
{
    const waste_config *c = &m->cfg;
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    waste_state_hdr h, want;
    state_fill(m, &want, 0);
    if (fread(&h, sizeof h, 1, f) != 1) { fclose(f); return -1; }
    /* every shape must match; pos and n_blockres are the payload */
    if (h.magic != want.magic || h.version != want.version ||
        h.n_layers != want.n_layers || h.hidden != want.hidden ||
        h.kda_heads != want.kda_heads || h.kda_dim != want.kda_dim ||
        h.conv_k != want.conv_k || h.n_heads != want.n_heads ||
        h.qk_nope != want.qk_nope || h.qk_rope != want.qk_rope ||
        h.v_head != want.v_head || h.attn_res_block != want.attn_res_block) {
        fclose(f);
        return -2;                       /* state does not belong to this model */
    }

    const int H = c->kda_heads, D = c->kda_dim, C = H * D;
    const int qd = c->qk_nope + c->qk_rope;
    int rc = 0;
    for (int L = 0; L < c->n_layers && !rc; L++) {
        if (c->kda_layer[L]) {
            if (fread(m->S[L], sizeof(float), (size_t)H * D * D, f) != (size_t)H * D * D) rc = -1;
            const size_t cn = (size_t)3 * C * (c->conv_k - 1);
            if (!rc && fread(m->conv[L], sizeof(float), cn, f) != cn) rc = -1;
        } else {
            int32_t nkv = 0;
            if (fread(&nkv, sizeof nkv, 1, f) != 1) { rc = -1; break; }
            if (nkv < 0 || nkv > m->kv_cap) { rc = -1; break; }
            const size_t kn = (size_t)nkv * c->n_heads * qd;
            const size_t vn = (size_t)nkv * c->n_heads * c->v_head;
            if (kn && fread(m->kcache[L], sizeof(float), kn, f) != kn) rc = -1;
            if (!rc && vn && fread(m->vcache[L], sizeof(float), vn, f) != vn) rc = -1;
            m->n_kv[L] = nkv;
        }
    }
    m->n_blockres = h.n_blockres;
    if (!rc && c->attn_res_block && h.n_blockres > 0) {
        const size_t n = (size_t)h.n_blockres * c->hidden;
        if (fread(m->blockres, sizeof(float), n, f) != n) rc = -1;
    }
    if (!rc && fread(m->x, sizeof(float), (size_t)c->hidden, f) != (size_t)c->hidden) rc = -1;
    fclose(f);
    if (!rc && pos) *pos = h.pos;
    return rc;
}

