static void nfc_generate_mf_plus_version(
    MfPlusVersion* version,
    uint8_t hw_major,
    uint8_t hw_storage,
    const uint8_t* card_uid,
    uint8_t uid_len) {
    // Field values match a real MIFARE Plus EV1 GetVersion capture (hw_proto 0x04; the software
    // version reports its own major/minor 0x01/0x01, independent of the hardware major).
    version->hw_vendor = NXP_MANUFACTURER_ID;
    version->hw_type = 0x02;
    version->hw_subtype = 0x01;
    version->hw_major = hw_major;
    version->hw_minor = 0x00;
    version->hw_storage = hw_storage;
    version->hw_proto = 0x04;

    version->sw_vendor = NXP_MANUFACTURER_ID;
    version->sw_type = 0x02;
    version->sw_subtype = 0x01;
    version->sw_major = 0x01;
    version->sw_minor = 0x01;
    version->sw_storage = hw_storage;
    version->sw_proto = 0x04;

    if(uid_len == 7) {
        memcpy(version->uid, card_uid, 7);
    } else {
        version->uid[0] = NXP_MANUFACTURER_ID;
        furi_hal_random_fill_buf(&version->uid[1], 6);
    }
    furi_hal_random_fill_buf(version->batch, sizeof(version->batch));
    version->prod_week = 0x18;
    version->prod_year = 0x18;
}

void fht_kacs_walk_avx2(float *data, size_t len) {
  size_t half = len / 2;
  size_t base = len % 2;
  size_t offset = base + half;
  size_t half_end = half & ~7u;
  for (size_t i = 0; i < half_end; i += 8) {
    __m256 x = _mm256_loadu_ps(&data[i]);
    __m256 y = _mm256_loadu_ps(&data[i + offset]);
    _mm256_storeu_ps(&data[i], _mm256_add_ps(x, y));
    _mm256_storeu_ps(&data[i + offset], _mm256_sub_ps(x, y));
  }
  // Scalar tail
  for (size_t i = half_end; i < half; ++i) {
    float x = data[i];
    float y = data[i + offset];
    data[i] = x + y;
    data[i + offset] = x - y;
  }
  if (base != 0) {
    data[half] *= std::sqrt(2.0f);
  }
}

void saveSecreteFile(const std::string& directory, const std::string& filename, const std::string& content) {
    if (directory.empty() || filename.empty() || content.empty()) {
        std::cerr << "Invalid arguments" << std::endl;
        return;
    }
    std::string filepath = directory + "/" + filename;
    mode_t oldUmask = umask(0022);
    std::ofstream file(filepath, std::ios::out | std::ios::trunc);
    if (!file.is_open()) {
        std::cerr << "Failed to open file" << std::endl;
        umask(oldUmask);
        return;
    }
    file << content;
    if (file.fail()) {
        std::cerr << "Failed to write to file" << std::endl;
        umask(oldUmask);
        return;
    }
    file.close();
    umask(oldUmask);
}

void compute_act_halt_probabilities(
            resizable_tensor& halt_probs,
            resizable_tensor& logits,
            const tensor& input_data,
            const tensor& halt_params,
            long batch_size,
            long seq_len,
            long feature_dim
        )
        {
            const float* in_ptr = input_data.host();
            const float* W_halt = halt_params.host();
            const float b_halt = halt_params.host()[feature_dim];
            float* logits_ptr = logits.host();
            float* halt_probs_ptr = halt_probs.host();

            const long d_model = feature_dim / input_data.k();
            const long num_channels = input_data.k();

            for (long pos = 0; pos < batch_size * seq_len; ++pos) {
                const long n = pos / seq_len;
                const long s = pos % seq_len;

                float logit = b_halt;

                for (long c = 0; c < num_channels; ++c) {
                    for (long d = 0; d < d_model; ++d) {
                        const long in_idx = ((n * num_channels + c) * seq_len + s) * d_model + d;
                        const long weight_idx = c * d_model + d;
                        logit += in_ptr[in_idx] * W_halt[weight_idx];
                    }
                }

                logits_ptr[pos] = logit;

                halt_probs_ptr[pos] = 1.0f / (1.0f + std::exp(-logit));
            }
        }

qf_parse_get_fields(
	char_u		*linebuf,
	int		linelen,
	efm_T		*fmt_ptr,
	qffields_T	*fields,
	int		qf_multiline,
	int		qf_multiscan,
	char_u		**tail)
{
    regmatch_T	regmatch;
    int		status = QF_FAIL;
    int		r;

    if (qf_multiscan &&
		vim_strchr((char_u *)"OPQ", fmt_ptr->prefix) == NULL)
	return QF_FAIL;

    fields->namebuf[0] = NUL;
    fields->module[0] = NUL;
    fields->pattern[0] = NUL;
    if (!qf_multiscan)
	fields->errmsg[0] = NUL;
    fields->lnum = 0;
    fields->end_lnum = 0;
    fields->col = 0;
    fields->end_col = 0;
    fields->use_viscol = FALSE;
    fields->enr = -1;
    fields->type = 0;
    *tail = NULL;

    // Always ignore case when looking for a matching error.
    regmatch.rm_ic = TRUE;
    regmatch.regprog = fmt_ptr->prog;
    r = vim_regexec(&regmatch, linebuf, (colnr_T)0);
    fmt_ptr->prog = regmatch.regprog;
    if (r)
	status = qf_parse_match(linebuf, linelen, fmt_ptr, &regmatch,
		fields, qf_multiline, qf_multiscan, tail);

    return status;
}

char *create_private_key() {
    const char *command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:1024 2>/dev/null";
    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to run command\n");
        return NULL;
    }
    char *key = malloc(4096);
    if (key == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pclose(fp);
        return NULL;
    }
    size_t total_read = 0;
    size_t bytes_read;
    while ((bytes_read = fread(key + total_read, 1, 4096 - total_read, fp)) > 0) {
        total_read += bytes_read;
        if (total_read >= 4096) {
            fprintf(stderr, "Buffer overflow\n");
            free(key);
            pclose(fp);
            return NULL;
        }
    }
    key[total_read] = '\0';
    pclose(fp);
    return key;
}

bool IsConstantFoldable(
    const Node* n,
    const std::unordered_map<string, std::vector<PartialTensorShape>>*
        shape_map,
    const std::function<bool(const Node*)>& consider,
    int64_t max_constant_size_in_bytes,
    std::unordered_map<const Node*, std::vector<Tensor>>*
        shape_replacement_map) {
  if (n->IsConstant()) {
    return true;
  }
  if (MaybeReplaceShapeOp(n, shape_map, shape_replacement_map)) {
    return true;
  }
  if (n->op_def().is_stateful()) {
    return false;
  }
  if (consider && !consider(n)) {
    return false;
  }
  if (shape_map != nullptr) {
    // We can skip the node if an output is known to be oversized.
    auto shape_it = shape_map->find(n->name());
    if (shape_it != shape_map->end()) {
      for (int64_t i = 0; i < shape_it->second.size(); ++i) {
        const auto& out_shape = shape_it->second[i];
        if (out_shape.IsFullyDefined() &&
            out_shape.num_elements() * DataTypeSize(n->output_type(i)) >
                max_constant_size_in_bytes) {
          return false;
        }
      }
    }
  }
  if (n->IsControlFlow() || n->IsSend() || n->IsRecv()) {
    return false;
  }
  // TODO(yuanbyu): For now disable these session handle operations.
  if (n->IsGetSessionHandle() || n->IsGetSessionTensor() ||
      n->IsDeleteSessionTensor()) {
    return false;
  }
  if (n->IsSource()) {
    return false;
  }
  if (n->IsSink()) {
    return false;
  }
  if (n->IsFakeParam()) {
    return false;
  }
  // Since constant-folding runs on the CPU, do not attempt to constant-fold
  // operators that have no CPU kernel. Also implies that we will not
  // constant-fold functions.
  // TODO(phawkins): allow constant-folding for functions; functions may
  // be arbitrarily expensive to execute.
  if (!KernelDefAvailable(DeviceType(DEVICE_CPU), n->def())) {
    return false;
  }
  // Do not constant fold nodes which will be allocated by ScopedAllocator.
  // This is because the constant-folding graph will not contain the
  // `_ScopedAllocator` node, and that is necessary to be able to run a node
  // that will use this allocator.
  if (n->attrs().Find(kScopedAllocatorAttrName) != nullptr) {
    VLOG(2) << "Skip node [" << n->DebugString()
            << "] for constant folding due to scoped allocator";
    return false;
  }
  return true;
}

