std::string getUser(sqlite3* db, const std::string& username, const std::string& password) {
    std::string query = "SELECT userInfo FROM users WHERE username = '" + username + "' AND password = '" + password + "'";
    sqlite3_stmt* stmt;
    std::string userInfo;
    if (sqlite3_prepare_v2(db, query.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
        return "";
    }
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        userInfo = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
    }
    sqlite3_finalize(stmt);
    return userInfo;
}

char* decode_json_web_token(const char* token, const char* key) {
    jwt_t* jwt = NULL;
    int ret = jwt_decode(&jwt, token, NULL, 0);
    if (ret != 0) {
        return strdup("{}");
    }
    char* claims = jwt_get_grants_json(jwt, NULL);
    if (!claims) {
        jwt_free(jwt);
        return strdup("{}");
    }
    jwt_free(jwt);
    return claims;
}

VOID  _tx_timer_interrupt(VOID)
{
UINT    saved_posture;

    saved_posture =  _tx_thread_smp_protect();

    _tx_timer_interrupt_active++;
    _tx_win32_debug_entry_insert("TIMER INTERRUPT", __FILE__, __LINE__);

    _tx_timer_system_clock++;

    if (*_tx_timer_current_ptr)
    {
        _tx_timer_expired =  TX_TRUE;
    }
    else
    {
        _tx_timer_current_ptr++;
        if (_tx_timer_current_ptr == _tx_timer_list_end)
        {
            _tx_timer_current_ptr =  _tx_timer_list_start;
        }
    }

    if (_tx_timer_expired != TX_FALSE)
    {
        _tx_timer_expiration_process();
    }

    _tx_thread_time_slice();

    _tx_timer_interrupt_active++;
    _tx_thread_smp_unprotect(saved_posture);
}

generate_octet_string(cms_context *cms, SECItem *encoded, SECItem *original)
{
