static void mctp_serial_push_header(struct mctp_serial *dev, unsigned char c)
{
	switch (dev->rxpos) {
	case 0:
		if (c == BYTE_FRAME)
			dev->rxpos++;
		else
			dev->rxstate = STATE_ERR;
		break;
	case 1:
		if (c == MCTP_SERIAL_VERSION) {
			dev->rxpos++;
			dev->rxfcs = crc_ccitt_byte(0, c);
		} else {
			dev->rxstate = STATE_ERR;
		}
		break;
	case 2:
		if (c > MCTP_SERIAL_FRAME_MTU) {
			dev->rxstate = STATE_ERR;
		} else {
			dev->rxlen = c;
			dev->rxpos = 0;
			dev->rxstate = STATE_DATA;
			dev->rxfcs = crc_ccitt_byte(dev->rxfcs, c);
		}
		break;
	}
}

int CNVMeDevice::CreateAdminQueues(void)
{
	// Allocate space for queues. ASQ is submission queue (array of commands)
	size_t uSqSize = sizeof(TNVMeCommand) * NVME_ADMIN_QUEUE_ENTRIES;
	size_t uCqSize = sizeof(TNVMeCompletion) * NVME_ADMIN_QUEUE_ENTRIES;

	void *pSq = m_Allocator.Allocate(uSqSize, NVME_PAGE_SIZE);
	if (!pSq) return NVME_STATUS_ERROR_NO_RESOURCE;
	void *pCq = m_Allocator.Allocate(uCqSize, NVME_PAGE_SIZE);
	if (!pCq) return NVME_STATUS_ERROR_NO_RESOURCE;

	memset(pSq, 0, uSqSize);
	memset(pCq, 0, uCqSize);

	m_AdminQueue.pSqVirt = pSq;
	m_AdminQueue.pCqVirt = pCq;
	m_AdminQueue.nSqPhys = PhysicalOf(pSq);
	m_AdminQueue.nCqPhys = PhysicalOf(pCq);

	u32 uAqa = ((NVME_ADMIN_QUEUE_ENTRIES - 1) << 16) | (NVME_ADMIN_QUEUE_ENTRIES - 1);
	MmioWrite32(NVME_REG_AQA, uAqa);
	MmioWrite64(NVME_REG_ASQ, m_AdminQueue.nSqPhys);
	MmioWrite64(NVME_REG_ACQ, m_AdminQueue.nCqPhys);

	m_AdminQueue.nSqTail = 0;
	m_AdminQueue.nCqHead = 0;
	m_AdminQueue.bCqPhase = true;

	return NVME_STATUS_OK;
}

void cache_keep_previous(httrackp *opt, cache_back *cache, const char *url_adr,
                         const char *url_fil, const char *url_save) {
  char BIGSTK previous_save[HTS_URLMAXSIZE * 2];
  htsblk r;

  if (!opt->cache || !cache_writable(cache) || url_save == NULL ||
      !strnotempty(url_save) || IS_DELAYED_EXT(url_save))
    return;
  if (cache->kept != NULL) {
    const char *const key =
        concat(OPT_GET_BUFF(opt), OPT_GET_BUFF_SIZE(opt), url_adr, url_fil);

    if (coucal_read(cache->kept, key, NULL) != 0)
      return; /* another attempt at the same link already stored it */
    coucal_add(cache->kept, key, 1);
  }
  /* Headers only: a kept entry carries no body, so nothing is read from the
     previous cache or from disk, whatever the file's size. */
  previous_save[0] = '\0';
  r = cache_readex_(opt, cache, url_adr, url_fil, NULL, NULL, previous_save, 1,
                    HTS_TRUE);
  /* The entry must name this very file: fexist() upstream proves only that
     something occupies the name, which a collision flip fills with another
     URL's file. */
  if (r.statuscode > 0 && strcmp(previous_save, url_save) == 0) {
    hts_log_print(opt, LOG_DEBUG, "keeping the previous cache entry for %s%s",
                  url_adr, url_fil);
    cache_add_ex(opt, cache, &r, url_adr, url_fil, url_save, opt->all_in_cache,
                 StringBuff(opt->path_html_utf8), HTS_TRUE);
  }
}

void DL_Dxf::addLayer(DL_CreationInterface* creationInterface) {
    // correct some invalid attributes for layers:
    attrib = creationInterface->getAttributes();
    if (attrib.getColor()==256 || attrib.getColor()==0) {
        attrib.setColor(7);
    }
    if (attrib.getWidth()<0) {
        attrib.setWidth(1);
    }

    std::string linetype = attrib.getLinetype();
    std::transform(linetype.begin(), linetype.end(), linetype.begin(), ::toupper);
    if (linetype=="BYLAYER" || linetype=="BYBLOCK") {
        attrib.setLinetype("CONTINUOUS");
    }

    // add layer
    std::string name = getStringValue(2, "");
    if (name.length()==0) {
        return;
    }

    creationInterface->addLayer(DL_LayerData(name, getIntValue(70, 0)));
}

int mbedtls_camellia_setkey_enc(mbedtls_camellia_context *ctx,
                                const unsigned char *key,
                                unsigned int keybits)
{
    int idx;
    size_t i;
    uint32_t *RK;
    unsigned char t[64];
    uint32_t SIGMA[6][2];
    uint32_t KC[16];
    uint32_t TK[20];

    RK = ctx->rk;

    memset(t, 0, 64);
    memset(RK, 0, sizeof(ctx->rk));

    switch (keybits) {
        case 128: ctx->nr = 3; idx = 0; break;
        case 192:
        case 256: ctx->nr = 4; idx = 1; break;
        default: return MBEDTLS_ERR_CAMELLIA_BAD_INPUT_DATA;
    }

    for (i = 0; i < keybits / 8; ++i) {
        t[i] = key[i];
    }

    if (keybits == 192) {
        for (i = 0; i < 8; i++) {
            t[24 + i] = ~t[16 + i];
        }
    }

    /*
     * Prepare SIGMA values
     */
    for (i = 0; i < 6; i++) {
        SIGMA[i][0] = MBEDTLS_GET_UINT32_BE(SIGMA_CHARS[i], 0);
        SIGMA[i][1] = MBEDTLS_GET_UINT32_BE(SIGMA_CHARS[i], 4);
    }

    /*
     * Key storage in KC
     * Order: KL, KR, KA, KB
     */
    memset(KC, 0, sizeof(KC));

    /* Store KL, KR */
    for (i = 0; i < 8; i++) {
        KC[i] = MBEDTLS_GET_UINT32_BE(t, i * 4);
    }

    /* Generate KA */
    for (i = 0; i < 4; ++i) {
        KC[8 + i] = KC[i] ^ KC[4 + i];
    }

    camellia_feistel(KC + 8, SIGMA[0], KC + 10);
    camellia_feistel(KC + 10, SIGMA[1], KC + 8);

    for (i = 0; i < 4; ++i) {
        KC[8 + i] ^= KC[i];
    }

    camellia_feistel(KC + 8, SIGMA[2], KC + 10);
    camellia_feistel(KC + 10, SIGMA[3], KC + 8);

    if (keybits > 128) {
        /* Generate KB */
        for (i = 0; i < 4; ++i) {
            KC[12 + i] = KC[4 + i] ^ KC[8 + i];
        }

        camellia_feistel(KC + 12, SIGMA[4], KC + 14);
        camellia_feistel(KC + 14, SIGMA[5], KC + 12);
    }

    /*
     * Generating subkeys
     */

    /* Manipulating KL */
    SHIFT_AND_PLACE(idx, 0);

    /* Manipulating KR */
    if (keybits > 128) {
        SHIFT_AND_PLACE(idx, 1);
    }

    /* Manipulating KA */
    SHIFT_AND_PLACE(idx, 2);

    /* Manipulating KB */
    if (keybits > 128) {
        SHIFT_AND_PLACE(idx, 3);
    }

    /* Do transpositions */
    for (i = 0; i < 20; i++) {
        if (transposes[idx][i] != -1) {
            RK[32 + 12 * idx + i] = RK[transposes[idx][i]];
        }
    }

    return 0;
}

