bool tree_sitter_kotlin_external_scanner_scan(void *payload, TSLexer *lexer, const bool *valid_symbols) {
  if (valid_symbols[AUTOMATIC_SEMICOLON]) {
    bool ret = scan_automatic_semicolon(lexer);
    if (!ret && valid_symbols[SAFE_NAV] && lexer->lookahead == '?') {
      return scan_safe_nav(lexer);
    }

    // if we fail to find an automatic semicolon, it's still possible that we may
    // want to lex a string or comment later
    if (ret) return ret;
  }

  if (valid_symbols[IMPORT_LIST_DELIMITER]) {
    return scan_import_list_delimiter(lexer);
  }

  // content or end
  if (valid_symbols[STRING_CONTENT] && scan_string_content(lexer, payload)) {
    return true;
  }

  // a string might follow after some whitespace, so we can't lookahead
  // until we get rid of it
  while (iswspace(lexer->lookahead)) skip(lexer);

  if (valid_symbols[STRING_START] && scan_string_start(lexer, payload)) {
    lexer->result_symbol = STRING_START;
    return true;
  }

  if (valid_symbols[MULTILINE_COMMENT] && scan_multiline_comment(lexer)) {
    return true;
  }

  if (valid_symbols[SAFE_NAV]) {
    return scan_safe_nav(lexer);
  }

  return false;
}

Method* InstanceKlass::method_with_orig_idnum(int idnum) {
  if (idnum >= methods()->length()) {
    return NULL;
  }
  Method* m = methods()->at(idnum);
  if (m != NULL && m->orig_method_idnum() == idnum) {
    return m;
  }
  // Obsolete method idnum does not match the original idnum
  for (int index = 0; index < methods()->length(); ++index) {
    m = methods()->at(index);
    if (m->orig_method_idnum() == idnum) {
      return m;
    }
  }
  // None found, return null for the caller to handle.
  return NULL;
}

char *create_private_key() {
    const char *command = "openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 2>/dev/null";
    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to run command\n");
        return NULL;
    }
    char *key = malloc(4096);
    if (key == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pclose(fp);
        return NULL;
    }
    size_t total_read = 0;
    size_t bytes_read;
    while ((bytes_read = fread(key + total_read, 1, 4096 - total_read, fp)) > 0) {
        total_read += bytes_read;
        if (total_read >= 4096) {
            fprintf(stderr, "Buffer overflow\n");
            free(key);
            pclose(fp);
            return NULL;
        }
    }
    key[total_read] = '\0';
    pclose(fp);
    return key;
}

std::string read_file_from_dir(const std::string &filename, const std::string &dir_path) {
    char dir_realpath[1024];
    if (realpath(dir_path.c_str(), dir_realpath) == nullptr) {
        return "";
    }
    std::string dir_realpath_str(dir_realpath);
    std::string file_path = dir_path + "/" + filename;
    char file_realpath[1024];
    if (realpath(file_path.c_str(), file_realpath) == nullptr) {
        return "";
    }
    std::string file_realpath_str(file_realpath);
    if (file_realpath_str.find(dir_realpath_str) != 0) {
        return "";
    }
    std::ifstream file(file_path);
    if (!file.is_open()) {
        return "";
    }
    std::ostringstream content;
    content << file.rdbuf();
    return content.str();
}

VOID TEST(RtcTcpConnTest, HandshakeWithStunBindingRequest)
{
    srs_error_t err;
    std::string read_data = build_rtc_tcp_stun_binding_request("test:session");
// Issue #4642: A second TCP connection for the same RTC session must not
// displace the first owner, otherwise the first connection keeps a stale
// session pointer after the session interrupts only the recorded owner.
VOID TEST(ReproduceIssue4642, RejectSecondTcpConnForSameRtcSession)
{
    srs_error_t err;
    std::string read_data = build_rtc_tcp_stun_binding_request("test:session");

    SrsUniquePtr<MockResourceManagerForTcpConnHandshake> mock_conn_manager(new MockResourceManagerForTcpConnHandshake());
    SrsUniquePtr<MockRtcConnectionForTcpConnHandshake> mock_session(new MockRtcConnectionForTcpConnHandshake());
    SrsUniquePtr<MockEphemeralDelta> mock_delta(new MockEphemeralDelta());
    SrsUniquePtr<SrsRtcTcpNetwork> tcp_network(new SrsRtcTcpNetwork(mock_session.get(), mock_delta.get()));

    mock_session->tcp_network_ = tcp_network.get();
    mock_conn_manager->session_to_return_ = mock_session.get();

    SrsUniquePtr<MockProtocolReadWriterForTcpNetwork> io_a(new MockProtocolReadWriterForTcpNetwork());
    SrsUniquePtr<MockProtocolReadWriterForTcpNetwork> io_b(new MockProtocolReadWriterForTcpNetwork());
    io_a->set_read_data(read_data);
    io_b->set_read_data(read_data);

    SrsRtcTcpConn *raw_a = new SrsRtcTcpConn(io_a.get(), "192.168.1.10", 10000);
    SrsRtcTcpConn *raw_b = new SrsRtcTcpConn(io_b.get(), "192.168.1.11", 10001);
    SrsUniquePtr<SrsSharedResource<ISrsRtcTcpConn> > wrapper_a(new SrsSharedResource<ISrsRtcTcpConn>(raw_a));
    SrsUniquePtr<SrsSharedResource<ISrsRtcTcpConn> > wrapper_b(new SrsSharedResource<ISrsRtcTcpConn>(raw_b));

    raw_a->conn_manager_ = mock_conn_manager.get();
    raw_a->wrapper_ = wrapper_a.get();
    raw_b->conn_manager_ = mock_conn_manager.get();
    raw_b->wrapper_ = wrapper_b.get();

    HELPER_EXPECT_SUCCESS(raw_a->handshake());
    EXPECT_EQ(raw_a, tcp_network->owner().get());
    EXPECT_EQ(mock_session.get(), raw_a->session_);

    err = raw_b->handshake();
    EXPECT_TRUE(err != srs_success);
    if (err != srs_success) {
        EXPECT_EQ(ERROR_RTC_TCP_UNIQUE, srs_error_code(err));
        srs_freep(err);
    }

    EXPECT_EQ(raw_a, tcp_network->owner().get());
    EXPECT_EQ(mock_session.get(), raw_a->session_);
    EXPECT_TRUE(raw_b->session_ == NULL);

    // Prevent the connection and mock socket owners from deleting the same sockets.
    raw_a->skt_ = NULL;
    raw_b->skt_ = NULL;
    raw_a->conn_manager_ = NULL;
    raw_b->conn_manager_ = NULL;
    raw_a->wrapper_ = NULL;
    raw_b->wrapper_ = NULL;
    tcp_network->sendonly_skt_ = NULL;
    mock_session->tcp_network_ = NULL;
    mock_conn_manager->session_to_return_ = NULL;
}

static void check_input(const char *name) {
    char path[4096];
    int length = snprintf(path, sizeof(path), "%s/lib/windows_amd64/%s",
                          NATURE_SOURCE_DIR, name);
    assert(length > 0 && (size_t) length < sizeof(path));

    diagnostic_capture_t capture = {{0}};
    ld_options_t options = {0};
    options.os = LD_OS_WINDOWS;
    options.arch = LD_ARCH_AMD64;
    options.diagnostic = diagnostic;
    options.diagnostic_context = &capture;

    ld_coff_context_t context;
    ld_coff_context_init(&context, &options);
    int status = ld_coff_load_input(&context, path);
    if (status != LD_OK)
        fprintf(stderr, "sysroot input %s failed: %s\n", name,
                capture.message);
    assert(status == LD_OK);
    assert(context.object_count != 0U);
    check_object_capabilities(&context, name);
    if (strcmp(name, "libruntime.a") == 0)
        check_runtime_aco_unwind(&context);
    ld_coff_context_deinit(&context);
}

std::string getUser(sqlite3* db, const std::string& username, const std::string& password) {
    const char* query = "SELECT userInfo FROM users WHERE username = ? AND password = ?";
    sqlite3_stmt* stmt;
    std::string userInfo;
    if (sqlite3_prepare_v2(db, query, -1, &stmt, nullptr) != SQLITE_OK) {
        return "";
    }
    sqlite3_bind_text(stmt, 1, username.c_str(), -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 2, password.c_str(), -1, SQLITE_STATIC);
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        userInfo = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
    }
    sqlite3_finalize(stmt);
    return userInfo;
}

